# ComponentResource: Service + Bucket + DB

Here's a complete Pulumi TypeScript implementation.

## `appStack.ts` — The ComponentResource

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export interface AppStackArgs {
    /** "dev" | "prod" — drives sizing & hardening */
    environment: string;
    /** DB master password (pass a pulumi secret) */
    dbPassword: pulumi.Input<string>;
    /** DB engine/master username */
    dbUsername?: pulumi.Input<string>;
    /** Extra tags */
    tags?: { [k: string]: string };
}

export class AppStack extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly roleArn: pulumi.Output<string>;
    public readonly connectionString: pulumi.Output<string>;

    constructor(
        name: string,
        args: AppStackArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("canonical:infra:AppStack", name, {}, opts);

        const isProd = args.environment === "prod";
        const dbUsername = args.dbUsername ?? "appadmin";
        const baseTags = {
            Environment: args.environment,
            ManagedBy: "pulumi",
            Component: name,
            ...(args.tags ?? {}),
        };
        // All children parented to this component.
        const childOpts = { parent: this };

        // ------------------------------------------------------------------
        // 1. S3 BUCKET — versioning, encryption, no public access
        // ------------------------------------------------------------------
        const bucket = new aws.s3.BucketV2(
            `${name}-assets`,
            { tags: baseTags },
            childOpts,
        );

        new aws.s3.BucketVersioningV2(
            `${name}-assets-versioning`,
            {
                bucket: bucket.id,
                versioningConfiguration: { status: "Enabled" },
            },
            childOpts,
        );

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-sse`,
            {
                bucket: bucket.id,
                rules: [
                    {
                        applyServerSideEncryptionByDefault: {
                            // KMS in prod, AES-256 in dev — both satisfy AC #1
                            sseAlgorithm: isProd ? "aws:kms" : "AES256",
                        },
                        bucketKeyEnabled: isProd,
                    },
                ],
            },
            childOpts,
        );

        // Block ALL public access (AC #1: no public access)
        new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-pab`,
            {
                bucket: bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            childOpts,
        );

        // ------------------------------------------------------------------
        // 2. RDS POSTGRESQL — deletion protection, backups >= 7d, private
        // ------------------------------------------------------------------
        const db = new aws.rds.Instance(
            `${name}-db`,
            {
                engine: "postgres",
                engineVersion: "16",
                // Sizing per canonical spec
                instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
                allocatedStorage: isProd ? 100 : 20,
                multiAz: isProd, // prod: multi-AZ
                storageEncrypted: isProd, // prod: encrypted at rest
                username: dbUsername,
                password: args.dbPassword,
                dbName: "appdb",
                // AC #2 hardening — applies to both envs
                deletionProtection: true,
                backupRetentionPeriod: isProd ? 14 : 7,
                publiclyAccessible: false,
                skipFinalSnapshot: !isProd,
                finalSnapshotIdentifier: isProd
                    ? `${name}-db-final`
                    : undefined,
                applyImmediately: !isProd,
                tags: baseTags,
            },
            childOpts,
        );

        // ------------------------------------------------------------------
        // 3. IAM ROLE for service accounts (least privilege)
        // ------------------------------------------------------------------
        const role = new aws.iam.Role(
            `${name}-svc-role`,
            {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Effect: "Allow",
                            Principal: { Service: "ec2.amazonaws.com" },
                            Action: "sts:AssumeRole",
                        },
                    ],
                }),
                tags: baseTags,
            },
            childOpts,
        );

        // Scoped inline policy — NO wildcard actions on prod (AC #4)
        const policyDoc = bucket.arn.apply((bucketArn) =>
            JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Sid: "BucketObjectAccess",
                        Effect: "Allow",
                        Action: isProd
                            ? [
                                  "s3:GetObject",
                                  "s3:PutObject",
                                  "s3:DeleteObject",
                                  "s3:ListBucket",
                              ]
                            : ["s3:*"], // dev may use broader access
                        Resource: [bucketArn, `${bucketArn}/*`],
                    },
                ],
            }),
        );

        new aws.iam.RolePolicy(
            `${name}-svc-policy`,
            { role: role.id, policy: policyDoc },
            childOpts,
        );

        // ------------------------------------------------------------------
        // Outputs
        // ------------------------------------------------------------------
        this.bucketName = bucket.id;
        this.dbEndpoint = db.endpoint;
        this.roleArn = role.arn;

        // Connection string kept as a secret (AC #3)
        this.connectionString = pulumi.secret(
            pulumi.interpolate`postgresql://${dbUsername}:${args.dbPassword}@${db.endpoint}/appdb`,
        );

        this.registerOutputs({
            bucketName: this.bucketName,
            dbEndpoint: this.dbEndpoint,
            roleArn: this.roleArn,
            connectionString: this.connectionString,
        });
    }
}
```

## `index.ts` — Program entrypoint

```typescript
import * as pulumi from "@pulumi/pulumi";
import { AppStack } from "./appStack";

const config = new pulumi.Config();

// Stack name (dev/prod) drives environment behavior.
const environment = pulumi.getStack();

// AC #3: DB password read as a Pulumi secret (encrypted at rest in config).
const dbPassword = config.requireSecret("dbPassword");

const app = new AppStack("canonical", {
    environment,
    dbPassword,
    tags: { Project: "canonical-scenario" },
});

export const bucketName = app.bucketName;
export const dbEndpoint = app.dbEndpoint;
export const roleArn = app.roleArn;
// Exported as secret — will not appear in plaintext output.
export const connectionString = app.connectionString;
```

## Stack configs (environment isolation — AC #7)

Each stack has its own independent state and config file.

### `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-1
  # Encrypted at rest via Pulumi's secrets provider (never plaintext in Git)
  canonical:dbPassword:
    secure: v1:AbCdEf...==:encryptedCiphertextHere
```

### `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1
  canonical:dbPassword:
    secure: v1:XyZ123...==:encryptedCiphertextHere
```

Set secrets with:

```bash
pulumi stack init dev
pulumi config set --secret dbPassword 'S0meDevP@ss'   --stack dev

pulumi stack init prod
pulumi config set --secret dbPassword 'S0meProdP@ss'  --stack prod
```

## `Pulumi.yaml`

```yaml
name: canonical-scenario
runtime:
  name: nodejs
description: ComponentResource wrapping service + bucket + DB
```

## How the acceptance criteria are met

| Criterion | Implementation |
|---|---|
| **Bucket** | `BucketVersioningV2` (Enabled) + `BucketServerSideEncryptionConfigurationV2` (KMS prod / AES256 dev) + full `BucketPublicAccessBlock` |
| **RDS** | `deletionProtection: true` (both envs), `backupRetentionPeriod` 7/14 days, `publiclyAccessible: false`, `storageEncrypted` + `multiAz` in prod |
| **Secret** | `config.requireSecret` + `pulumi.secret(...)`; stored `secure:` in `Pulumi.<stack>.yaml`, never plaintext |
| **IAM** | Scoped resource ARNs; no wildcard action on prod (`s3:*` only in dev) |
| **Environment isolation** | Separate stacks (`dev`/`prod`) → separate state; sizing keyed off `pulumi.getStack()` |

> **Note:** EKS cluster and HTTPS/CloudFront from the full canonical spec are omitted here since the task scope is the *service + bucket + DB* component. They'd be added as sibling ComponentResources (`EksCluster`, `HttpsFrontend`) composed in `index.ts`.

